#!/usr/bin/env node
/**
 * Git's commit-msg hook: removes AI credit lines from the commit message, and names the Claude Code session that made
 * the commit. Git runs it in every repo through a hook entry in the global .gitconfig.
 */

import { execFileSync } from "node:child_process";
import { readFileSync, realpathSync, writeFileSync } from "node:fs";
import { fileURLToPath } from "node:url";

const AI_TOOLS = "claude|anthropic|copilot|cursor|codex|openai|chatgpt|gpt-[0-9]|gemini|aider|devin|codeium|windsurf|tabnine|sourcegraph";

/** "Generated with Claude Code", "🤖 Generated by Codex" and similar bylines. */
const AI_BYLINE = new RegExp(`^[^\\p{L}\\p{N}]*generated (with|by|using) .*(${AI_TOOLS})`, "iu");

const CO_AUTHOR = /^\s*co-authored-by:/i;

/** A co-author whose whole name is a tool, such as "Claude" or "GitHub Copilot". People named Claude Monet keep credit. */
const AI_CO_AUTHOR_NAME = new RegExp(`^\\s*co-authored-by:\\s*(github\\s+)?(${AI_TOOLS})([-a-z]*\\[bot\\])?\\s*(<|$)`, "i");

const AI_COMPANY_EMAIL =
  /<[^>]*@(anthropic\.com|openai\.com|cursor\.(com|sh)|aider\.chat|codeium\.com|windsurf\.com|tabnine\.com|cognition\.ai)>/i;

/** Whether one line of a commit message credits an AI tool. */
export const creditsAi = (line) =>
  AI_BYLINE.test(line) || (CO_AUTHOR.test(line) && (AI_CO_AUTHOR_NAME.test(line) || AI_COMPANY_EMAIL.test(line)));

/** The message without its AI credit lines. A message that would end up empty is returned as it was. */
export const withoutAiCredit = (message) => {
  const kept = message
    .split("\n")
    .filter((line) => !creditsAi(line))
    .join("\n");

  return kept.trim() === "" ? message : kept;
};

const addSessionLine = (messageFile, sessionId) => {
  execFileSync("git", [
    "interpret-trailers",
    "--in-place",
    "--if-exists",
    "addIfDifferent",
    "--trailer",
    `Claude-Session-Id: ${sessionId}`,
    messageFile,
  ]);
};

const run = (messageFile) => {
  if (!messageFile) {
    return;
  }

  // Claude Code sets this in every shell it starts. `claude --resume <id>` reopens the session.
  const sessionId = process.env.CLAUDE_CODE_SESSION_ID;

  if (sessionId) {
    addSessionLine(messageFile, sessionId);
  }

  writeFileSync(messageFile, withoutAiCredit(readFileSync(messageFile, "utf8")));
};

const isRunDirectly = process.argv[1] && realpathSync(process.argv[1]) === fileURLToPath(import.meta.url);

if (isRunDirectly) {
  run(process.argv[2]);
}
